CREATE TABLE IF NOT EXISTS operaciones (id VARCHAR(36) PRIMARY KEY, request_key VARCHAR(80) NOT NULL UNIQUE, cuenta_id BIGINT NOT NULL, tipo VARCHAR(20) NOT NULL, monto DECIMAL(18,2) NOT NULL, creado VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(36) PRIMARY KEY, payload CLOB NOT NULL, enviado BOOLEAN NOT NULL DEFAULT FALSE);
